using StatusInfo = std::tuple<int, std::string, bool>;

StatusInfo query_resource(int id) {
    if (id > 100)
        return std::make_tuple(200, "OK", true);
    return {404, "Missing", false}; // C++17 direct init
}

// Unpacking via Structured Binding (C++17)
auto [code, message, found] = query_resource(50);

// Unpacking via std::get
StatusInfo result = query_resource(200);
int status_code = std::get<0>(result);
std::string msg_type = std::get<std::string>(result);

// Using std::tie to ignore values (C++11/14)
std::string msg;
std::tie(std::ignore, msg, std::ignore) = query_resource(10);
